create extension if not exists pgcrypto;

create type public.workspace_role as enum ('owner', 'admin', 'member', 'viewer');
create type public.project_status as enum ('active', 'archived', 'deleted');
create type public.project_visibility as enum ('private', 'workspace');

create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, avatar_url text, username text unique, bio text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.workspaces (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text, owner_id uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.workspace_members (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role public.workspace_role not null default 'member', created_at timestamptz not null default now(), unique(workspace_id, user_id));
create table public.projects (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, name text not null, slug text not null, description text, status public.project_status not null default 'active', visibility public.project_visibility not null default 'workspace', created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id, slug));
create table public.project_requirements (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, content text not null, version integer not null default 1 check (version > 0), created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());

create or replace function public.is_workspace_member(target_workspace uuid, target_user uuid default auth.uid()) returns boolean language sql security definer set search_path = public as $$ select exists (select 1 from public.workspace_members where workspace_id = target_workspace and user_id = target_user); $$;
create or replace function public.is_workspace_admin(target_workspace uuid, target_user uuid default auth.uid()) returns boolean language sql security definer set search_path = public as $$ select exists (select 1 from public.workspace_members where workspace_id = target_workspace and user_id = target_user and role in ('owner', 'admin')); $$;
create or replace function public.is_workspace_owner(target_workspace uuid, target_user uuid default auth.uid()) returns boolean language sql security definer set search_path = public as $$ select exists (select 1 from public.workspace_members where workspace_id = target_workspace and user_id = target_user and role = 'owner'); $$;

create index workspace_members_workspace_idx on public.workspace_members(workspace_id); create index workspace_members_user_idx on public.workspace_members(user_id); create index projects_workspace_idx on public.projects(workspace_id); create index projects_created_by_idx on public.projects(created_by); create index requirements_project_idx on public.project_requirements(project_id); create index requirements_created_by_idx on public.project_requirements(created_by);
create trigger profiles_updated_at before update on public.profiles for each row execute function public.set_updated_at(); create trigger workspaces_updated_at before update on public.workspaces for each row execute function public.set_updated_at(); create trigger projects_updated_at before update on public.projects for each row execute function public.set_updated_at(); create trigger requirements_updated_at before update on public.project_requirements for each row execute function public.set_updated_at();

alter table public.profiles enable row level security; alter table public.workspaces enable row level security; alter table public.workspace_members enable row level security; alter table public.projects enable row level security; alter table public.project_requirements enable row level security;
create policy profiles_self on public.profiles for all using (id = auth.uid()) with check (id = auth.uid());
create policy workspaces_insert on public.workspaces for insert with check (owner_id = auth.uid());
create policy workspace_members_access on public.workspace_members for select using (public.is_workspace_member(workspace_id)); create policy workspace_members_manage on public.workspace_members for all using (public.is_workspace_admin(workspace_id)) with check (public.is_workspace_admin(workspace_id));
create policy workspaces_access on public.workspaces for select using (public.is_workspace_member(id)); create policy workspaces_manage on public.workspaces for update using (public.is_workspace_admin(id)); create policy workspaces_delete on public.workspaces for delete using (public.is_workspace_owner(id));
create policy projects_access on public.projects for select using (public.is_workspace_member(workspace_id) and (visibility = 'workspace' or created_by = auth.uid())); create policy projects_insert on public.projects for insert with check (public.is_workspace_member(workspace_id) and created_by = auth.uid()); create policy projects_manage on public.projects for update using (public.is_workspace_member(workspace_id)); create policy projects_delete on public.projects for delete using (public.is_workspace_admin(workspace_id));
create policy requirements_access on public.project_requirements for select using (exists (select 1 from public.projects p where p.id = project_id and public.is_workspace_member(p.workspace_id))); create policy requirements_manage on public.project_requirements for all using (exists (select 1 from public.projects p where p.id = project_id and public.is_workspace_member(p.workspace_id))) with check (created_by = auth.uid());

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, full_name, avatar_url) values (new.id, new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'avatar_url'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.handle_new_workspace() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.workspace_members (workspace_id, user_id, role) values (new.id, new.owner_id, 'owner'); return new; end; $$;
create trigger on_workspace_created after insert on public.workspaces for each row execute function public.handle_new_workspace();